    14→
    15→abstract class FlinkCdcBatchListener(
    16→    val groupId: String,
    17→    val consumerCallbackManager: ConsumerCallbackManager,
    18→) : ConsumerSeekAware {
    19→    private val logger by logger()
    20→
    21→    interface ConsumerManager<K, V> {
    22→        fun records(): List<ConsumerRecord<K, V>>
    23→        fun commit()
    24→    }
    25→
    26→    fun <K, V> createConsumerManager(
    27→        data: List<ConsumerRecord<K, V>>,
    28→        consumer: Consumer<*, *>,
    29→        skipPredicate: (V) -> Boolean = { false },
    30→    ): ConsumerManager<K, V> = object : ConsumerManager<K, V> {
    31→        private val logger by logger()
    32→        private val offsetMap: MutableMap<TopicPartition, Long> = mutableMapOf()
    33→        private val seekMap: MutableMap<TopicPartition, Long> = mutableMapOf()
    34→        private val refinedData: MutableList<ConsumerRecord<K, V>> = mutableListOf()
    35→
    36→        init {
    37→            logger.info { "CommitManager created. data size: ${data.size}" }
    38→
    39→            data.groupBy { TopicPartition(it.topic(), it.partition()) }
    40→                .forEach { (tp, records) ->
    41→                    val refined: MutableList<ConsumerRecord<K, V>> = mutableListOf()
    42→
    43→                    if (skipPredicate(records.last().value())) {
    44→                        seekMap[tp] = records.last().offset()
    45→                        refined.addAll(records.dropLast(1))
    46→                    } else {
    47→                        refined.addAll(records)
    48→                    }
    49→
    50→                    offsetMap[tp] = refined.last().offset()
    51→                    refinedData.addAll(refined)
    52→                }
    53→        }
    54→
    55→        override fun records(): List<ConsumerRecord<K, V>> = refinedData.toList()
    56→
    57→        override fun commit() {
    58→            if (offsetMap.isEmpty()) {
    59→                logger.warn { "No offset to commit" }
    60→            }
    61→
    62→            offsetMap.forEach { (tp, offset) ->
    63→                consumer.commitSync(mapOf(tp to OffsetAndMetadata(offset)))
    64→            }
    65→
    66→            seekMap.forEach { (tp, offset) ->
    67→                val cbm = consumerCallbackManager.getConsumerCallback(groupId, tp.topic(), tp.partition())
    68→                cbm.callback.seek(tp.topic(), tp.partition(), offset)
    69→            }
    70→        }
    71→    }
    72→
    73→    override fun registerSeekCallback(callback: ConsumerSeekAware.ConsumerSeekCallback) {
    74→        // Do nothing
    75→    }
    76→
    77→    override fun onPartitionsAssigned(
    78→        assignments: MutableMap<TopicPartition, Long>,
    79→        callback: ConsumerSeekAware.ConsumerSeekCallback,
    80→    ) {
    81→        assignments.keys.forEach {
    82→            consumerCallbackManager.register(groupId, it.topic(), it.partition(), callback)
    83→        }
    84→    }
    85→
    86→    override fun onPartitionsRevoked(partitions: MutableCollection<TopicPartition>) {
    87→        partitions.forEach {
    88→            consumerCallbackManager.revoke(groupId, it.topic(), it.partition())
    89→        }
    90→    }
    91→
    92→    override fun onIdleContainer(
    93→        assignments: MutableMap<TopicPartition, Long>,
    94→        callback: ConsumerSeekAware.ConsumerSeekCallback,
    95→    ) {
    96→        assignments.keys.forEach {
    97→            checkToSeek(it.topic(), it.partition())
    98→        }
    99→    }
   100→
   101→    protected fun rewindIfNeeded() {
   102→        consumerCallbackManager.getAllConsumerCallbacks()
   103→            .forEach { c ->
   104→                if (c.shouldSeek) {
   105→                    logger.info {
   106→                        "[Consumer] Try to seek offset. " +
   107→                                "groupId=[${c.groupId}], topic=[${c.topic}], partition=[${c.partition}], offset=[${c.offset}]"
   108→                    }
   109→                    c.callback.seek(c.topic, c.partition, c.offset)
   110→                    c.reset()
   111→                }
   112→            }
   113→    }
   114→
   115→    protected fun checkToSeek(
   116→        topic: String,
   117→        partition: Int,
   118→    ) {
   119→        val c = consumerCallbackManager.getConsumerCallback(groupId, topic, partition)
   120→        if (c.shouldSeek) {
   121→            logger.info {
   122→                "[Consumer] Try to seek offset. " +
   123→                        "groupId=[$groupId], topic=[$topic], partition=[$partition], offset=[${c.offset}]"
   124→            }
   125→            c.callback.seek(topic, partition, c.offset)
   126→            c.reset()
   127→        }
   128→    }
   129→}

